import fs from 'node:fs'
const geo = JSON.parse(fs.readFileSync('/tmp/us-states.json','utf8'))
const names = new Set([
'Alabama','Arizona','Arkansas','California','Colorado','Connecticut','Delaware','Florida','Georgia','Idaho','Illinois','Indiana','Iowa','Kansas','Kentucky','Louisiana','Maine','Maryland','Massachusetts','Michigan','Minnesota','Mississippi','Missouri','Montana','Nebraska','Nevada','New Hampshire','New Jersey','New Mexico','New York','North Carolina','North Dakota','Ohio','Oklahoma','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming','Alaska','Hawaii'])
const abbr = {Alabama:'AL',Alaska:'AK',Arizona:'AZ',Arkansas:'AR',California:'CA',Colorado:'CO',Connecticut:'CT',Delaware:'DE',Florida:'FL',Georgia:'GA',Hawaii:'HI',Idaho:'ID',Illinois:'IL',Indiana:'IN',Iowa:'IA',Kansas:'KS',Kentucky:'KY',Louisiana:'LA',Maine:'ME',Maryland:'MD',Massachusetts:'MA',Michigan:'MI',Minnesota:'MN',Mississippi:'MS',Missouri:'MO',Montana:'MT',Nebraska:'NE',Nevada:'NV',NewHampshire:'NH',NewJersey:'NJ',NewMexico:'NM',NewYork:'NY',NorthCarolina:'NC',NorthDakota:'ND',Ohio:'OH',Oklahoma:'OK',Oregon:'OR',Pennsylvania:'PA',RhodeIsland:'RI',SouthCarolina:'SC',SouthDakota:'SD',Tennessee:'TN',Texas:'TX',Utah:'UT',Vermont:'VT',Virginia:'VA',Washington:'WA',WestVirginia:'WV',Wisconsin:'WI',Wyoming:'WY'}
// fix key mapping
const abbr2 = {Alabama:'AL',Alaska:'AK',Arizona:'AZ',Arkansas:'AR',California:'CA',Colorado:'CO',Connecticut:'CT',Delaware:'DE',Florida:'FL',Georgia:'GA',Hawaii:'HI',Idaho:'ID',Illinois:'IL',Indiana:'IN',Iowa:'IA',Kansas:'KS',Kentucky:'KY',Louisiana:'LA',Maine:'ME',Maryland:'MD',Massachusetts:'MA',Michigan:'MI',Minnesota:'MN',Mississippi:'MS',Missouri:'MO',Montana:'MT',Nebraska:'NE',Nevada:'NV','New Hampshire':'NH','New Jersey':'NJ','New Mexico':'NM','New York':'NY','North Carolina':'NC','North Dakota':'ND',Ohio:'OH',Oklahoma:'OK',Oregon:'OR',Pennsylvania:'PA','Rhode Island':'RI','South Carolina':'SC','South Dakota':'SD',Tennessee:'TN',Texas:'TX',Utah:'UT',Vermont:'VT',Virginia:'VA',Washington:'WA','West Virginia':'WV',Wisconsin:'WI',Wyoming:'WY'}
const D=Math.PI/180
function albers(lon,lat,lambda0=-96,phi0=37.5,phi1=29.5,phi2=45.5){
  const n=0.5*(Math.sin(phi1*D)+Math.sin(phi2*D))
  const C=Math.cos(phi1*D)**2+2*n*Math.sin(phi1*D)
  const rho0=Math.sqrt(C-2*n*Math.sin(phi0*D))/n
  const rho=Math.sqrt(C-2*n*Math.sin(lat*D))/n
  const theta=n*(lon-lambda0)*D
  return [rho*Math.sin(theta), rho0-rho*Math.cos(theta)]
}
function polys(f){ return f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates }
function projectFeature(f, proj){ return polys(f).map(poly=>poly.map(ring=>ring.map(([lon,lat])=>proj(lon,lat)))) }
function bbox(rings){let minx=Infinity,miny=Infinity,maxx=-Infinity,maxy=-Infinity;for(const poly of rings)for(const ring of poly)for(const [x,y] of ring){minx=Math.min(minx,x);maxx=Math.max(maxx,x);miny=Math.min(miny,y);maxy=Math.max(maxy,y)}return{minx,miny,maxx,maxy,w:maxx-minx,h:maxy-miny}}
function fitter(box, rect, keep=1){const s=Math.min(rect.w/box.w,rect.h/box.h)*keep;const ox=rect.x+(rect.w-box.w*s)/2;const oy=rect.y+(rect.h-box.h*s)/2;return ([x,y])=>({x:ox+(x-box.minx)*s,y:oy+(y-box.miny)*s})}

const lowerNames=[...names].filter(n=>!['Alaska','Hawaii'].includes(n))
const lowerFeats=geo.features.filter(f=>lowerNames.includes(f.properties.name))
const lowerProj=(lon,lat)=>albers(lon,lat)
const lowerRings=lowerFeats.map(f=>projectFeature(f,lowerProj))
const lowerBox=bbox(lowerRings)
// main area: x 30..970, y 20..500
const lowerFit=fitter(lowerBox,{x:30,y:18,w:940,h:478},1)
console.log('lower box',lowerBox, lowerBox.w/lowerBox.h)

const akFeat=geo.features.find(f=>f.properties.name==='Alaska')
const hiFeat=geo.features.find(f=>f.properties.name==='Hawaii')
const akProj=(lon,lat)=>albers(lon,lat,-154,64,55,65)
const hiProj=(lon,lat)=>albers(lon,lat,-157,20.5,19,22)
const akRings=projectFeature(akFeat,akProj)
const hiRings=projectFeature(hiFeat,hiProj)
const akBox=bbox(akRings), hiBox=bbox(hiRings)
const akFit=fitter(akBox,{x:38,y:505,w:230,h:100},.98)
const hiFit=fitter(hiBox,{x:770,y:512,w:190,h:88},.98)

function centroidOfPoly(poly){
  // area-weighted centroid of outer ring, accounting for absolute area
  const ring=poly[0]; let a=0,cx=0,cy=0
  for(let i=0,j=ring.length-1;i<ring.length;j=i++){
    const [x0,y0]=ring[j],[x1,y1]=ring[i]
    const f=x0*y1-x1*y0; a+=f; cx+=(x0+x1)*f; cy+=(y0+y1)*f
  }
  a*=0.5
  if(Math.abs(a)<1e-9) return {x:ring[0][0],y:ring[0][1],area:0}
  return {x:cx/(6*a),y:cy/(6*a),area:Math.abs(a)}
}
function geoCenter(rings){ // largest polygon, centroid
  let best=null
  for(const poly of rings){const c=centroidOfPoly(poly);if(!best||c.area>best.area)best=c}
  return best
}
function round(n){return Math.round(n*10)/10}

const states=[]
for(const f of lowerFeats){
  const name=f.properties.name
  const rings=projectFeature(f,lowerProj)
  const fitted=rings.map(poly=>poly.map(ring=>ring.map(([x,y])=>{const p=lowerFit([x,y]);return [round(p.x),round(p.y)]})))
  const c=geoCenter(fitted)
  const d=fitted.map(poly=>poly.map((ring,i)=>ring.map(([x,y],j)=>`${j===0?'M':'L'}${x} ${y}`).join('')+(i===0?'Z':'Z')).join('')).join('')
  states.push({name,abbr:abbr2[name],x:c.x,y:c.y,d,region:''})
}
// AK
{
  const rings=projectFeature(akFeat,akProj)
  const fitted=rings.map(poly=>poly.map(ring=>ring.map(([x,y])=>{const p=akFit([x,y]);return [round(p.x),round(p.y)]})))
  const c=geoCenter(fitted)
  const d=fitted.map(poly=>poly.map(ring=>ring.map(([x,y],j)=>`${j===0?'M':'L'}${x} ${y}`).join('Z')).join('')).join('')
  states.push({name:'Alaska',abbr:'AK',x:c.x,y:c.y,d,region:''})
}
{
  const rings=projectFeature(hiFeat,hiProj)
  const fitted=rings.map(poly=>poly.map(ring=>ring.map(([x,y])=>{const p=hiFit([x,y]);return [round(p.x),round(p.y)]})))
  const c=geoCenter(fitted)
  const d=fitted.map(poly=>poly.map(ring=>ring.map(([x,y],j)=>`${j===0?'M':'L'}${x} ${y}`).join('Z')).join('')).join('')
  states.push({name:'Hawaii',abbr:'HI',x:c.x,y:c.y,d,region:''})
}
// manual pin tweaks for crowded northeast
const tweaks={
  'Vermont':{x:842,y:150},'New Hampshire':{x:872,y:155},'Maine':{x:912,y:110},
  'Massachusetts':{x:884,y:181},'Rhode Island':{x:905,y:192},'Connecticut':{x:858,y:190},
  'New Jersey':{x:833,y:226},'Delaware':{x:818,y:249},'Maryland':{x:800,y:264},
  'District of Columbia':null
}
for(const s of states){ if(tweaks[s.name]) Object.assign(s,tweaks[s.name]) }
states.sort((a,b)=>a.name.localeCompare(b.name))
const out=`// Generated from PublicaMundi MappingAPI U.S. state boundaries (public domain Census-derived data).
// Projection: Albers conic with Alaska/Hawaii insets. Coordinates fit to a 1000 x 620 world.
export const STATE_PATHS = ${JSON.stringify(states)}\n`
fs.writeFileSync('states.js',out)
console.log('wrote', states.length, 'states')
console.log(states.map(s=>`${s.abbr}:${round(s.x)},${round(s.y)}`).join(' '))
EOF
