import fs from 'node:fs'
const geo=JSON.parse(fs.readFileSync('/tmp/us-states.json','utf8'))
const names=new Set(['Alabama','Arizona','Arkansas','California','Colorado','Connecticut','Delaware','Florida','Georgia','Idaho','Illinois','Indiana','Iowa','Kansas','Kentucky','Louisiana','Maine','Maryland','Massachusetts','Michigan','Minnesota','Mississippi','Missouri','Montana','Nebraska','Nevada','New Hampshire','New Jersey','New Mexico','New York','North Carolina','North Dakota','Ohio','Oklahoma','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming'])
const D=Math.PI/180
function albers(lon,lat,lambda0=-96,phi0=37.5,phi1=29.5,phi2=45.5){const n=0.5*(Math.sin(phi1*D)+Math.sin(phi2*D));const C=Math.cos(phi1*D)**2+2*n*Math.sin(phi1*D);const rho0=Math.sqrt(C-2*n*Math.sin(phi0*D))/n;const rho=Math.sqrt(C-2*n*Math.sin(lat*D))/n;const theta=n*(lon-lambda0)*D;return [rho*Math.sin(theta), rho0-rho*Math.cos(theta)]}
function polys(f){ return f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates }
function projectFeature(f, proj){ return polys(f).map(poly=>poly.map(ring=>ring.map(([lon,lat])=>proj(lon,lat)))) }
const lowerFeats=geo.features.filter(f=>names.has(f.properties.name))
const lowerRings=lowerFeats.map(f=>projectFeature(f,albers))
let minx=Infinity
let i=0
for(const poly of lowerRings){
 for(const ring of poly){
  for(const [x,y] of ring){
   if(!Number.isFinite(x)||!Number.isFinite(y)){ console.log('bad at state',lowerFeats[i].properties.name,x,y,typeof x, ring.length); process.exit() }
   minx=Math.min(minx,x)
  }
 }
 i++
}
console.log('minx',minx)
