import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { homedir } from 'node:os'
const runtime = join(homedir(), '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
for (let attempt = 1; attempt <= 8; attempt++) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  const t0 = Date.now()
  await page.goto('http://localhost:3000', { waitUntil: 'load' })
  await page.waitForFunction(() => document.fonts.status === 'loaded')
  const btn = page.locator('button, input[type="button"], input[type="submit"], [role="button"]').filter({ has: undefined })
  const candidates = await btn.all()
  let target
  for (const c of candidates) {
    if (!await c.isVisible() || !await c.isEnabled()) continue
    const label = await c.evaluate(el => el.getAttribute('aria-label') || el.value || el.textContent || '')
    if (/^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim())) { target = c; break }
  }
  if (!target) { console.log(attempt, 'not found'); await page.close(); continue }
  const box = await target.boundingBox()
  const info = await target.evaluate(el => {
    const r = el.getBoundingClientRect()
    const top = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2)
    return { r: { x: r.x, y: r.y, w: r.width, h: r.height }, top: top?.outerHTML.slice(0, 120), scrollY: window.scrollY, opacity: getComputedStyle(el).opacity }
  })
  try {
    await target.click({ trial: true, timeout: 2000 })
    console.log(attempt, 'trial ok', Date.now() - t0, 'ms', JSON.stringify(info), JSON.stringify(box))
    await target.click({ timeout: 2000, noWaitAfter: true })
    console.log(attempt, 'clicked overlay hidden', await page.locator('#startOverlay').isHidden())
  } catch (error) {
    console.log(attempt, 'FAIL', Date.now() - t0, 'ms', error.name, error.message.split('\n')[0], JSON.stringify(info), JSON.stringify(box))
  }
  await page.close()
}
await browser.close()

