import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { homedir } from 'node:os'
const runtime = join(homedir(), '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.addInitScript(() => {
  window.__gaps = []
  let last = performance.now()
  const raf = window.requestAnimationFrame.bind(window)
  window.requestAnimationFrame = cb => raf(t => {
    const now = performance.now()
    if (now - last > 120) window.__gaps.push({ gap: Math.round(now - last), at: Math.round(now) })
    last = now
    cb(t)
  })
  new PerformanceObserver(list => {
    for (const entry of list.getEntries()) window.__gaps.push({ longtask: Math.round(entry.duration), at: Math.round(entry.startTime) })
  }).observe({ type: 'longtask', buffered: true })
})
await page.goto('http://localhost:3000', { waitUntil: 'load' })
await page.waitForTimeout(6000)
console.log(await page.evaluate(() => window.__gaps))
await browser.close()

