import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { homedir } from 'node:os'
const runtime = join(homedir(), '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('http://localhost:3000')
const res = await page.evaluate(async () => {
  const { STATES } = await import('./states.js')
  const canvas = document.createElement('canvas')
  canvas.width = 1050; canvas.height = 530
  canvas.style.cssText = 'position:fixed;inset:0;z-index:9999'
  document.body.append(canvas)
  const c = canvas.getContext('2d')
  const paths = STATES.map(s => ({ p: new Path2D(s.d), abbr: s.abbr }))
  const scale = .9, ox = 20, oy = 10
  const measure = (label, draw) => new Promise(resolve => {
    let frames = 0; const start = performance.now()
    function f() {
      const t = performance.now(); draw(t); c.getImageData(0,0,1,1)
      frames++
      if (performance.now() - start < 2000) requestAnimationFrame(f)
      else resolve({ label, fps: frames / 2, js: performance.now() - start })
    }
    requestAnimationFrame(f)
  })
  const base = (t) => {
    c.setTransform(1,0,0,1,0,0); c.fillStyle='#eee'; c.fillRect(0,0,1050,530)
    c.setTransform(scale,0,0,scale,ox,oy)
    for (const {p} of paths) { c.fillStyle='#fbf4e6'; c.fill(p); c.strokeStyle='rgba(21,38,60,.58)'; c.lineWidth=1.05; c.stroke(p) }
  }
  const noStates = (t) => {
    c.setTransform(1,0,0,1,0,0); c.fillStyle='#eee'; c.fillRect(0,0,1050,530)
    c.setTransform(scale,0,0,scale,ox,oy)
    for (let i=0;i<600;i++){c.beginPath();c.arc((i*37)%920,(i*53)%560,.9,0,7);c.fill()}
  }
  return [await measure('states', base), await measure('dots', noStates)]
})
console.log(res)
await browser.close()

content.text:
The synthetic test itself got 0.5fps and 2fps, because it created a fixed canvas at z-index 9999 over the game page, and the game loop was also running plus the page. But it reflects heavy. Also `getImageData` each frame forces readback (very expensive) — that's why. Not a valid test. Could navigate to blank page and add canvas. But anyway.

The real question: can we improve deliverable enough without overcomplicating? The user didn't ask for performance. The game is done. The only broken thing is capture auto-start intermittently, which we can fix by removing transform animation. Do that, then verify capture several times. Also maybe reduce continuous rendering on menu for start screen smoothness (worth it, low risk). I'd also consider throttling `updateLiveUI` to avoid per-frame text writes—it's simple and good practice. Let's implement:

1. Start overlay card entrance: remove transform from keyframes (fade only). Keep `animation: card-in ...`; rename to `card-fade`? Could keep name but no transform. End card also uses card-in; fade only is acceptable. Maybe add slight translate via an inner element? Not needed.

2. `frame`: skip draw/update when `game.phase === 'menu'` (start overlay visible) to avoid continuous rendering behind overlay. But `resetBoard()` may happen then `renderStaticUI` + `updateAllUI`; map drawn once at init. Need ensure draw is called at least once after init. It is called by the first frame (phase menu). If we skip immediately, never draws. So handle:

```
let menuDrawn = false;
function frame(now){
  ...
  if (game.phase === 'menu') {
     if (!menuDrawn) { draw(now); menuDrawn = true; }
     requestAnimationFrame(frame);
     return;
  }
  menuDrawn = false;
  update(dt, now);
  draw(now);
  updateLiveUI(now);
  requestAnimationFrame(frame);
}
```

But after end screen, phase may become 'over'/'won'; draw continues for effects? Let's check endGame sets phase. update() returns early if phase !== 'playing' but draw continues, which is needed for end overlay effects behind. Fine.

When game ends and "Run it back" calls resetBoard then startGame, phase playing so resumes. If resetBoard only showed menu? index has again button calls startGame directly likely. Fine.

However when help/states dialog opens, game phase playing, update returns early but draw continues—fine.

3. Skip redundant DOM updates in updateLiveUI: keep a cache for hint and route meta etc. But not necessary for capture. It may improve gameplay smoothness. Let's see updateLiveUI is called every frame and writes attributes/text. We can reduce by checking textContent before assigning. Function `setText(el, text)` helper. There are 6 text writes; classList toggles set same state no-op mostly. aria setAttribute every frame triggers mutation; could check. Fill width changes every frame anyway. That's one style update. Overall minor.

Given time, do 1 & 2 and verify capture repeatedly (5 times). Also test start screen screenshot remains visually good.

Let's implement.

